using System;
using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using DesktopCritters.Core;
namespace DesktopCritters;
public static class SmokeTests {
 private static void Save(string file,DrawingVisual visual,int width,int height){var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
 public static int Run(string directory){Directory.CreateDirectory(directory);var app=new System.Windows.Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int code=1;app.Startup+=(_,_)=>{try{CharacterTests.Run(directory);var w=new World(1440,900,11);var overlay=new Overlay(w,()=>{},()=>{});overlay.Show();overlay.SetPassthrough(true);if(!overlay.NativePassthrough)throw new Exception("Transparent input style not set");overlay.SetPassthrough(false);if(overlay.NativePassthrough)throw new Exception("Interactive input style not restored");overlay.SetPassthrough(true);Console.WriteLine("PASS: native transparent window and click-through style toggle");
  var dirty=new World(1440,900,5);dirty.Bugs.Clear();dirty.Eggs.Clear();dirty.Foods.Clear();var roach=new Bug{Id=1,Species=Species.Roach,P=new V(480,550),Bulk=.7,ShownBulk=.7};var ant=new Bug{Id=2,Species=Species.Ant,P=new V(1080,580),Bulk=1,ShownBulk=1};dirty.Bugs.Add(roach);dirty.Bugs.Add(ant);dirty.AddFood(new V(380,220),Snack.Banquet);dirty.AddFood(new V(1050,220),Snack.Pizza);dirty.Swat(roach.P);dirty.Splats[0].Age=.3;dirty.SlapAge=1;
  var visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1440,900));Art.Draw(dirty,c,false);}Save(Path.Combine(directory,"windows-battlefield.png"),visual,1440,900);Console.WriteLine("PASS: WPF textures, giant food, liquid and live specimen render");
  dirty.SweepAt(roach.P);dirty.Sweeps[0].Age=.28;visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1440,900));Art.Draw(dirty,c,false);}Save(Path.Combine(directory,"windows-broom.png"),visual,1440,900);Console.WriteLine("PASS: WPF broom cleaning effect renders");
  var flight=new World(1200,800,42);flight.Bugs.Clear();flight.Eggs.Clear();flight.Foods.Clear();var flyer=new Bug{Id=1,Species=Species.Roach,P=new V(600,400),Bulk=.58,ShownBulk=.58};flight.Bugs.Add(flyer);if(!flight.BeginFlight(flyer))throw new Exception("Flight could not start");flyer.Flight!.Elapsed=flyer.Flight.Duration*.4;flight.Fly(flyer,0);visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1200,800));Art.Draw(flight,c,false);}Save(Path.Combine(directory,"windows-flight.png"),visual,1200,800);Console.WriteLine("PASS: native flying wings, moving body and separated shadow render");
  var visitors=new World(1200,800,42);visitors.Bugs.Clear();visitors.Eggs.Clear();visitors.Foods.Clear();int vi=0;foreach(var kind in Enum.GetValues<InvaderKind>()){visitors.Invaders.Add(new Invader{Id=100+vi,Kind=kind,P=new V(230+vi%3*350,230+vi/3*300),Phase=1.4,Health=100,Cooldown=1.4});vi++;}visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1200,800));Art.Draw(visitors,c,false);}Save(Path.Combine(directory,"windows-visitors.png"),visual,1200,800);Console.WriteLine("PASS: all five native foreign visitor bodies render");
  var lay=new World(1200,800,42);lay.Bugs.Clear();lay.Eggs.Clear();lay.Foods.Clear();lay.MarkShelter(new V(650,400));var mother=new Bug{Id=7,Species=Species.Roach,P=new V(570,400),Angle=Math.PI,Breeder=true,Bulk=.28,ShownBulk=.28};lay.Bugs.Add(mother);lay.Eggs.Add(lay.EmittedEgg(mother,20));for(int n=0;n<3;n++){lay.Eggs[0].LayAge=n*1.4;visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1200,800));Art.Draw(lay,c,false);}Save(Path.Combine(directory,"windows-egg-extrusion-"+n+".png"),visual,1200,800);}Console.WriteLine("PASS: native egg extrusion stages and folder occlusion render");
  var poison=new World(1200,800,42);poison.Bugs.Clear();poison.Eggs.Clear();poison.Foods.Clear();poison.Interactive=true;poison.Bugs.Add(new Bug{Id=1,Species=Species.Roach,P=new V(600,400)});poison.Bugs.Add(new Bug{Id=2,Species=Species.Ant,P=new V(640,390)});poison.Spray(new V(600,400));poison.Sprays[0].Age=.25;visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1200,800));Art.Draw(poison,c,false);}Save(Path.Combine(directory,"windows-insecticide.png"),visual,1200,800);Console.WriteLine("PASS: native aerosol, mist and killed insect remains render");
  var host=new Host(app);host.Start();host.SelectTool(Tool.Food);if(host.Overlay.NativePassthrough)throw new Exception("Tool selection did not enable input");host.Work();if(!host.Overlay.NativePassthrough)throw new Exception("Companion mode did not restore passthrough");host.Panel.Hide();host.ShowPanel();if(!host.Panel.IsVisible||host.Panel.Owner!=host.Overlay)throw new Exception("Control panel recovery or ownership failed");Console.WriteLine("PASS: startup, tray, input-mode switching and control panel recovery");host.Panel.UpdateLayout();host.Panel.Refresh();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(host.Panel.ActualWidth),(int)Math.Ceiling(host.Panel.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(host.Panel);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(directory,"windows-controls.png")))png.Save(stream);var gallery=new CharacterGallery(host){Owner=host.Overlay};gallery.Show();gallery.UpdateLayout();var galleryBitmap=new RenderTargetBitmap((int)Math.Ceiling(gallery.ActualWidth),(int)Math.Ceiling(gallery.ActualHeight),96,96,PixelFormats.Pbgra32);galleryBitmap.Render(gallery);var galleryPng=new PngBitmapEncoder();galleryPng.Frames.Add(BitmapFrame.Create(galleryBitmap));using(var output=File.Create(Path.Combine(directory,"windows-characters.png")))galleryPng.Save(output);gallery.Close();Console.WriteLine("PASS: character gallery renders and closes independently");host.Quitting=true;host.Panel.Close();overlay.Close();Console.WriteLine("PASS: native control panel layout renders");code=0;
 }catch(Exception e){Console.Error.WriteLine(e);}finally{app.Shutdown();}};app.Run();return code;}
}
